import Testing
@testable import AIChat

struct SSEParserTests {
    private func chunk(_ content: String) -> String {
        #"data: {"id":"c1","object":"chat.completion.chunk","choices":[{"index":0,"delta":{"content":"\#(content)"},"finish_reason":null}]}"#
    }

    // MARK: - Дельты

    @Test func parsesContentDelta() {
        #expect(SSEParser.parse(line: chunk("Hello")) == .delta("Hello"))
    }

    @Test func keepsLeadingSpaceAndEscapesInsideContent() {
        #expect(SSEParser.parse(line: chunk(#" world\n\"q\" é"#)) == .delta(" world\n\"q\" é"))
    }

    @Test func acceptsDataWithoutSpaceAfterColon() {
        let line = #"data:{"choices":[{"delta":{"content":"x"}}]}"#
        #expect(SSEParser.parse(line: line) == .delta("x"))
    }

    @Test func stripsTrailingCarriageReturn() {
        #expect(SSEParser.parse(line: chunk("Hi") + "\r") == .delta("Hi"))
        #expect(SSEParser.parse(line: "data: [DONE]\r") == .done)
    }

    @Test(arguments: [
        // Первый чанк: только роль, без текста.
        #"data: {"choices":[{"index":0,"delta":{"role":"assistant","content":null}}]}"#,
        #"data: {"choices":[{"index":0,"delta":{"role":"assistant"}}]}"#,
        // Пустой текст.
        #"data: {"choices":[{"index":0,"delta":{"content":""}}]}"#,
        // Последний чанк Groq: пустые choices + статистика.
        #"data: {"choices":[],"x_groq":{"id":"req_1","usage":{"total_tokens":10}}}"#,
        // Конец генерации без текста.
        #"data: {"choices":[{"index":0,"delta":{},"finish_reason":"stop"}]}"#,
    ])
    func ignoresChunksWithoutText(line: String) {
        #expect(SSEParser.parse(line: line) == nil)
    }

    // MARK: - [DONE]

    @Test(arguments: ["data: [DONE]", "data:[DONE]", "data: [DONE]  "])
    func recognizesDone(line: String) {
        #expect(SSEParser.parse(line: line) == .done)
    }

    // MARK: - Пустые data: и служебные строки

    @Test(arguments: ["", "data:", "data: ", "data:   ", ": keep-alive", ":", "event: message", "id: 42", "retry: 1000"])
    func ignoresEmptyAndServiceLines(line: String) {
        #expect(SSEParser.parse(line: line) == nil)
    }

    // MARK: - Обрезанные строки, не-JSON и мусор

    @Test(arguments: [
        #"data: {"choices":[{"delta":{"content":"Hel"#,
        #"data: {"choices":[{"delta":"#,
        #"data: {"#,
        #"{"choices":[{"delta":{"content":"no prefix"}}]}"#,
        "data: hello",
        "data: 42",
        "data: [\"array\"]",
        "data: null",
        "dat",
        "garbage \u{0}\u{1}",
        #"data: {"unexpected":"shape"}"#,
    ])
    func ignoresTruncatedAndNonJSONLines(line: String) {
        #expect(SSEParser.parse(line: line) == nil)
    }

    // MARK: - Ошибка внутри data:

    @Test func parsesErrorPayload() {
        let line = #"data: {"error":{"message":"Rate limit reached","type":"tokens","code":"rate_limit_exceeded"}}"#
        #expect(SSEParser.parse(line: line) == .error(StreamErrorPayload(type: "tokens", code: "rate_limit_exceeded")))
    }

    @Test func parsesErrorPayloadWithoutTypeAndCode() {
        let line = #"data: {"error":{"message":"Something broke","type":null}}"#
        #expect(SSEParser.parse(line: line) == .error(StreamErrorPayload(type: nil, code: nil)))
    }

    /// Текст ошибки сервера в событие не попадает — он не должен дойти до UI.
    @Test func errorPayloadDoesNotKeepServerMessage() {
        let line = #"data: {"error":{"message":"secret details","type":"server_error"}}"#
        let event = SSEParser.parse(line: line)
        #expect(!String(describing: event).contains("secret details"))
    }

    // MARK: - Поток целиком

    @Test func parsesTypicalGroqStream() {
        let lines = [
            #"data: {"choices":[{"delta":{"role":"assistant","content":""}}]}"#,
            "",
            chunk("Hel"),
            "",
            chunk("lo"),
            ": ping",
            chunk("!"),
            #"data: {"choices":[],"x_groq":{"usage":{}}}"#,
            "data: [DONE]",
        ]
        let events = lines.compactMap(SSEParser.parse(line:))
        #expect(events == [.delta("Hel"), .delta("lo"), .delta("!"), .done])
    }
}

import Foundation

/// Событие потока OpenAI-совместимого `/chat/completions` со `stream: true`.
enum SSEEvent: Hashable, Sendable {
    /// Очередной кусок текста ответа (непустой).
    case delta(String)
    /// `data: [DONE]` — штатный конец потока.
    case done
    /// `data: {"error": …}` — ошибка пришла внутри потока при HTTP 200.
    case error(StreamErrorPayload)
}

/// Поля ошибки, по которым её можно классифицировать. Текст `message` сознательно
/// не храним: сырой ответ сервера не должен попасть в UI или логи.
struct StreamErrorPayload: Hashable, Sendable, Decodable {
    let type: String?
    let code: String?
}

/// Построчный SSE-парсер. Строки приходят из `URLSession.AsyncBytes.lines`, который
/// уже режет поток по переводам строки и пропускает пустые строки; у Groq одно
/// событие — одна строка `data:`, поэтому собирать многострочные события не нужно.
///
/// Всё, что не похоже на осмысленное событие (комментарии `:`, `event:`/`id:`,
/// пустые `data:`, не-JSON, обрезанный JSON, чанки без текста), возвращает `nil`:
/// мусор в потоке не должен обрывать ответ.
enum SSEParser {
    static func parse(line rawLine: String) -> SSEEvent? {
        var line = Substring(rawLine)
        if line.hasSuffix("\r") { line = line.dropLast() }
        guard line.hasPrefix("data:") else { return nil }

        var payload = line.dropFirst("data:".count)
        // По спецификации SSE после двоеточия убирается ровно один пробел.
        if payload.hasPrefix(" ") { payload = payload.dropFirst() }

        let trimmed = payload.trimmingCharacters(in: .whitespaces)
        guard !trimmed.isEmpty else { return nil }
        if trimmed == "[DONE]" { return .done }

        let data = Data(trimmed.utf8)
        let decoder = JSONDecoder()
        if let envelope = try? decoder.decode(ErrorEnvelope.self, from: data) {
            return .error(envelope.error)
        }
        guard let chunk = try? decoder.decode(Chunk.self, from: data) else { return nil }

        let text = chunk.choices.compactMap(\.delta?.content).joined()
        return text.isEmpty ? nil : .delta(text)
    }

    private struct ErrorEnvelope: Decodable {
        let error: StreamErrorPayload
    }

    private struct Chunk: Decodable {
        struct Choice: Decodable {
            let delta: Delta?
        }

        struct Delta: Decodable {
            let content: String?
        }

        let choices: [Choice]
    }
}

import Foundation

/// Код и заголовки ответа. Своя `Sendable`-структура вместо `HTTPURLResponse`,
/// чтобы спокойно передавать её между задачами.
struct HTTPResponseHead: Hashable, Sendable {
    let statusCode: Int
    /// Имена заголовков в нижнем регистре.
    let headers: [String: String]

    init(statusCode: Int, headers: [String: String] = [:]) {
        self.statusCode = statusCode
        self.headers = Dictionary(headers.map { ($0.key.lowercased(), $0.value) }, uniquingKeysWith: { first, _ in first })
    }

    func value(forHeader name: String) -> String? {
        headers[name.lowercased()]
    }
}

enum HTTPStreamEvent: Hashable, Sendable {
    /// Всегда первое событие.
    case head(HTTPResponseHead)
    /// Строка тела без перевода строки.
    case line(String)
}

/// Транспорт для стриминга: отдаёт заголовок ответа, затем тело построчно.
/// Отмена потребителя (или `break` из цикла) должна прерывать запрос.
protocol HTTPLineStreaming: Sendable {
    func stream(_ request: URLRequest) -> AsyncThrowingStream<HTTPStreamEvent, Error>
}

/// Живая реализация на `URLSession.bytes(for:)`.
struct URLSessionLineStreamer: HTTPLineStreaming {
    let session: URLSession

    init(session: URLSession = .shared) {
        self.session = session
    }

    func stream(_ request: URLRequest) -> AsyncThrowingStream<HTTPStreamEvent, Error> {
        let session = session
        return AsyncThrowingStream { continuation in
            let task = Task {
                do {
                    let (bytes, response) = try await session.bytes(for: request)
                    guard let http = response as? HTTPURLResponse else { throw URLError(.badServerResponse) }
                    let headers = http.allHeaderFields.reduce(into: [String: String]()) { result, field in
                        if let name = field.key as? String, let value = field.value as? String {
                            result[name] = value
                        }
                    }
                    continuation.yield(.head(HTTPResponseHead(statusCode: http.statusCode, headers: headers)))
                    for try await line in bytes.lines {
                        continuation.yield(.line(line))
                    }
                    continuation.finish()
                } catch {
                    continuation.finish(throwing: error)
                }
            }
            continuation.onTermination = { _ in task.cancel() }
        }
    }
}

import Foundation

/// Groq, OpenAI-совместимый `/chat/completions` со `stream: true`.
///
/// Получает уже собранную историю (фильтрацию и обрезку делают репозиторий и
/// `ChatService`); сам добавляет только системный промпт, если его нет.
struct GroqProvider: LLMProvider {
    static let endpoint = URL(string: "https://api.groq.com/openai/v1/chat/completions")
    static let systemPrompt = "Answer in the language of the user's last message. Be concise."
    static let maxCompletionTokens = 1024

    private let configuration: GroqConfiguration
    private let transport: any HTTPLineStreaming

    init(configuration: GroqConfiguration, transport: any HTTPLineStreaming = URLSessionLineStreamer()) {
        self.configuration = configuration
        self.transport = transport
    }

    var displayName: LocalizedStringResource {
        // «openai/gpt-oss-120b» → «gpt-oss-120b».
        let model = configuration.model.split(separator: "/").last.map(String.init) ?? configuration.model
        return "Groq · \(model)"
    }

    func streamReply(to messages: [LLMMessage]) -> AsyncThrowingStream<String, Error> {
        let configuration = configuration
        let transport = transport
        return AsyncThrowingStream { continuation in
            let task = Task {
                do {
                    let request = try Self.makeRequest(messages: messages, configuration: configuration)
                    try await Self.run(request, transport: transport) { continuation.yield($0) }
                    continuation.finish()
                } catch {
                    // «Stop» — не ошибка: поток просто заканчивается.
                    if Task.isCancelled {
                        continuation.finish()
                    } else {
                        continuation.finish(throwing: error)
                    }
                }
            }
            continuation.onTermination = { _ in task.cancel() }
        }
    }

    // MARK: - Запрос

    static func makeRequest(messages: [LLMMessage], configuration: GroqConfiguration) throws -> URLRequest {
        guard let endpoint else { throw LLMError(kind: .unknown) }
        var request = URLRequest(url: endpoint)
        request.httpMethod = "POST"
        request.setValue("Bearer \(configuration.apiKey)", forHTTPHeaderField: "Authorization")
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.setValue("text/event-stream", forHTTPHeaderField: "Accept")
        request.timeoutInterval = 60

        var context = messages
        if context.first?.role != .system {
            context.insert(LLMMessage(role: .system, content: systemPrompt), at: 0)
        }
        let body = RequestBody(
            model: configuration.model,
            messages: context.map { .init(role: $0.role.rawValue, content: $0.content) },
            stream: true,
            reasoningEffort: "low",
            includeReasoning: false,
            maxCompletionTokens: maxCompletionTokens
        )
        let encoder = JSONEncoder()
        encoder.keyEncodingStrategy = .convertToSnakeCase
        request.httpBody = try encoder.encode(body)
        return request
    }

    struct RequestBody: Codable, Equatable {
        struct Message: Codable, Equatable {
            let role: String
            let content: String
        }

        let model: String
        let messages: [Message]
        let stream: Bool
        let reasoningEffort: String
        let includeReasoning: Bool
        let maxCompletionTokens: Int
    }

    // MARK: - Ответ

    private static func run(
        _ request: URLRequest,
        transport: any HTTPLineStreaming,
        emit: (String) -> Void
    ) async throws {
        var head: HTTPResponseHead?
        for try await event in transport.stream(request) {
            switch event {
            case let .head(responseHead):
                head = responseHead
                guard responseHead.statusCode == 200 else { throw LLMError(kind: .unknown) }
            case let .line(line):
                guard head != nil else { continue }
                switch SSEParser.parse(line: line) {
                case let .delta(text): emit(text)
                case .done: return
                case .error: throw LLMError(kind: .server)
                case nil: continue
                }
            }
        }
        try Task.checkCancellation()
        // Соединение закрылось без `[DONE]` — ответ, скорее всего, обрезан.
        throw LLMError(kind: .unknown)
    }
}

import Foundation
import Synchronization
@testable import AIChat

/// Транспорт по сценарию: отдаёт заданные события, потом заканчивает поток,
/// бросает ошибку или «висит» до отмены. Запоминает запросы и факт отмены.
final class StubLineStreamer: HTTPLineStreaming {
    enum Ending: Sendable {
        case finish
        case fail(any Error)
        case hang
    }

    private struct State {
        var requests: [URLRequest] = []
        var terminatedEarly = false
    }

    private let events: [HTTPStreamEvent]
    private let ending: Ending
    private let state = Mutex(State())

    init(events: [HTTPStreamEvent], ending: Ending = .finish) {
        self.events = events
        self.ending = ending
    }

    /// 200 и строки SSE.
    convenience init(sse lines: [String], ending: Ending = .finish) {
        self.init(events: [.head(HTTPResponseHead(statusCode: 200))] + lines.map(HTTPStreamEvent.line), ending: ending)
    }

    var requests: [URLRequest] { state.withLock(\.requests) }
    /// Потребитель бросил поток до его конца (отмена или `break`).
    var terminatedEarly: Bool { state.withLock(\.terminatedEarly) }

    func stream(_ request: URLRequest) -> AsyncThrowingStream<HTTPStreamEvent, Error> {
        state.withLock { $0.requests.append(request) }
        let events = events
        let ending = ending
        return AsyncThrowingStream { continuation in
            let task = Task {
                for event in events {
                    continuation.yield(event)
                    await Task.yield()
                }
                switch ending {
                case .finish:
                    continuation.finish()
                case let .fail(error):
                    continuation.finish(throwing: error)
                case .hang:
                    while !Task.isCancelled { try? await Task.sleep(for: .seconds(60)) }
                }
            }
            continuation.onTermination = { [state] termination in
                if case .cancelled = termination {
                    state.withLock { $0.terminatedEarly = true }
                }
                task.cancel()
            }
        }
    }
}

import Foundation
import Testing
@testable import AIChat

struct GroqProviderTests {
    /// Синтетический ключ: настоящий в тестах не используется.
    private let configuration = GroqConfiguration(apiKey: "test-key", model: "openai/gpt-oss-120b")

    private func chunk(_ content: String) -> String {
        #"data: {"choices":[{"index":0,"delta":{"content":"\#(content)"}}]}"#
    }

    private func body(of request: URLRequest) throws -> GroqProvider.RequestBody {
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return try decoder.decode(GroqProvider.RequestBody.self, from: try #require(request.httpBody))
    }

    // MARK: - Запрос

    @Test func buildsStreamingRequest() throws {
        let messages = [
            LLMMessage(role: .user, content: "Hi"),
            LLMMessage(role: .assistant, content: "Hello!"),
            LLMMessage(role: .user, content: "How are you?"),
        ]
        let request = try GroqProvider.makeRequest(messages: messages, configuration: configuration)

        #expect(request.httpMethod == "POST")
        #expect(request.url?.absoluteString == "https://api.groq.com/openai/v1/chat/completions")
        #expect(request.url?.query == nil)
        #expect(request.value(forHTTPHeaderField: "Authorization") == "Bearer test-key")
        #expect(request.value(forHTTPHeaderField: "Content-Type") == "application/json")
        #expect(request.value(forHTTPHeaderField: "Accept") == "text/event-stream")

        let body = try body(of: request)
        #expect(body.model == "openai/gpt-oss-120b")
        #expect(body.stream)
        #expect(body.reasoningEffort == "low")
        #expect(body.includeReasoning == false)
        #expect(body.maxCompletionTokens == 1024)
        #expect(body.messages.map(\.role) == ["system", "user", "assistant", "user"])
        #expect(body.messages.first?.content == GroqProvider.systemPrompt)
        #expect(body.messages.dropFirst().map(\.content) == ["Hi", "Hello!", "How are you?"])
    }

    @Test func bodyUsesSnakeCaseKeys() throws {
        let request = try GroqProvider.makeRequest(messages: [], configuration: configuration)
        let json = try #require(try JSONSerialization.jsonObject(with: try #require(request.httpBody)) as? [String: Any])
        #expect(Set(json.keys) == ["model", "messages", "stream", "reasoning_effort", "include_reasoning", "max_completion_tokens"])
    }

    @Test func keepsCallerSystemPrompt() throws {
        let messages = [LLMMessage(role: .system, content: "Custom"), LLMMessage(role: .user, content: "Hi")]
        let body = try body(of: GroqProvider.makeRequest(messages: messages, configuration: configuration))
        #expect(body.messages.map(\.content) == ["Custom", "Hi"])
    }

    @Test func displayNameShowsShortModelName() {
        let provider = GroqProvider(configuration: configuration, transport: StubLineStreamer(sse: []))
        #expect(String(localized: provider.displayName) == "Groq · gpt-oss-120b")
    }

    // MARK: - Стриминг

    @Test func streamsDeltasUntilDone() async {
        let transport = StubLineStreamer(sse: [
            #"data: {"choices":[{"delta":{"role":"assistant","content":""}}]}"#,
            chunk("Hel"),
            ": ping",
            chunk("lo"),
            "garbage",
            chunk(" world"),
            "data: [DONE]",
        ])
        let provider = GroqProvider(configuration: configuration, transport: transport)

        let result = await collect(provider.streamReply(to: [LLMMessage(role: .user, content: "Hi")]))

        #expect(result.text == "Hello world")
        #expect(result.error == nil)
        #expect(transport.requests.count == 1)
    }

    /// После `[DONE]` дальше не читаем.
    @Test func ignoresLinesAfterDone() async {
        let transport = StubLineStreamer(sse: [chunk("A"), "data: [DONE]", chunk("B")], ending: .hang)
        let provider = GroqProvider(configuration: configuration, transport: transport)

        let result = await collect(provider.streamReply(to: []))

        #expect(result.text == "A")
        #expect(result.error == nil)
    }

    /// Соединение закрылось без `[DONE]` — это ошибка, а не тихо обрезанный ответ.
    @Test func endWithoutDoneIsError() async {
        let provider = GroqProvider(configuration: configuration, transport: StubLineStreamer(sse: [chunk("Half")]))

        let result = await collect(provider.streamReply(to: []))

        #expect(result.text == "Half")
        #expect(result.error is LLMError)
    }

    // MARK: - Отмена

    @Test func cancellationFinishesWithoutErrorAndAbortsRequest() async throws {
        let transport = StubLineStreamer(sse: [chunk("Partial")], ending: .hang)
        let provider = GroqProvider(configuration: configuration, transport: transport)
        let task = Task {
            let result = await collect(provider.streamReply(to: []))
            return (result, Task.isCancelled)
        }

        try await Task.sleep(for: .milliseconds(100))
        task.cancel()
        let (result, wasCancelled) = await task.value

        #expect(result.error == nil)
        #expect(wasCancelled)
        // Запрос к транспорту прерван, а не брошен висеть.
        try await waitUntil { transport.terminatedEarly }
    }

    /// Транспорт бросил `CancellationError` уже после отмены — наружу не выходит.
    @Test func cancellationErrorFromTransportIsSwallowed() async throws {
        let transport = StubLineStreamer(sse: [chunk("x")], ending: .hang)
        let provider = GroqProvider(configuration: configuration, transport: transport)
        let stream = provider.streamReply(to: [])
        let task = Task { await collect(stream) }

        try await Task.sleep(for: .milliseconds(100))
        task.cancel()
        let result = await task.value

        #expect(result.error == nil)
    }

    private func waitUntil(timeout: Duration = .seconds(2), _ condition: () -> Bool) async throws {
        let deadline = ContinuousClock.now + timeout
        while !condition() {
            guard ContinuousClock.now < deadline else { throw TimeoutError() }
            try await Task.sleep(for: .milliseconds(10))
        }
    }
}

